import status from '@/generated/review-status.json';
import credits from '../../content/credits.json';
import speakerFile from '../../content/audio/speakers.json';

/** How much of the Czech a native speaker has checked (generated by npm run review:status). */
export const reviewStatus = status as { total: number; reviewed: number; areas: Record<string, { total: number; reviewed: number }> };

const AREA_NAMES: Record<string, string> = {
  units: 'Line A lessons', words: 'Word decks', exam: 'Exam practice', guides: 'Guides', alphabet: 'Sounds', calendar: 'Holidays and name days',
  grammar: 'Grammar pages', verbs: 'Verb tables', lexicon: 'Noun lexicon', phrases: 'Phrase deck', emergency: 'Emergency cards', overheard: 'Overheard in Prague', idioms: 'Idioms', lines: 'Station notes',
};
export const areaName = (a: string) => AREA_NAMES[a] ?? a;

export function reviewLine(): string {
  const { reviewed, total } = reviewStatus;
  const n = (x: number) => x.toLocaleString('en-GB');
  return reviewed === 0 ? `Czech not yet checked by a native speaker (0 of ${n(total)} items)` : `Czech checked by a native speaker: ${n(reviewed)} of ${n(total)} items`;
}

export const reviewerCredits = (credits.reviewers as { name: string }[]).map((r) => r.name);
export const speakerCredits = Object.values(speakerFile.speakers as Record<string, { name: string }>).map((s) => s.name);
